-- ═════════════════════════════════════════════════════════════════════════════
-- Formulación del "FOR-DE-144 Plan de acción 2024 consolidado.xlsx" en el formulario "Plan de Acción 2024"
-- 248 indicadores (hoja FORMULACIÓN) y su distribución por facultades (hoja FORMULACIÓN Y SEG. FACULTADES).
-- Solo formulación: el seguimiento queda vacío para diligenciarlo en el sistema.
--
-- Antes de ejecutar:
--   1. Haz un respaldo de la base de datos.
--   2. Ejecútalo UNA sola vez (si lo corres dos veces se duplican los indicadores).
--   3. El formulario "Plan de Acción 2024" se CREA si no existe (si ya existe, se usa). Comprueba el SELECT inicial: debe mostrar su id.
--   4. @ef es el estado en que quedan los indicadores:
--        2 = PUBLICADOS en Formulación (aparecen en Seguimiento)  ← por defecto, igual que las cargas de 2026
--        0 = BORRADORES de Formulación (hay que publicarlos después)
--   5. @anio es el año que se guarda en cada indicador (2024, como dice el Excel).
--
-- Los ids nuevos se calculan a partir del mayor id actual (@base), así que no pisa ningún registro existente.
-- Línea, motor, proyecto y objetivo salen del catálogo (tablas lineas_estrategicas, motores y proyectos) buscándolos por CÓDIGO (L1, M1, P1);
-- así quedan con el nombre exacto que usa el sistema. Las dependencias, con el nombre de la tabla cargos.
-- Las facultades se buscan por nombre en la tabla facultades.
-- ═════════════════════════════════════════════════════════════════════════════
SET NAMES utf8mb4;
-- Crea el formulario "Plan de Acción 2024" si todavía no existe (siempre disponible, activo, año 2024)
SELECT 'Plan de Acción 2024', 'FOR-DE-144 Plan de acción 2024 consolidado', 'libre', NULL, NULL, 1, 2024
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM formularios WHERE titulo LIKE 'Plan de Acci%n 2024%');
SET @formulario = (SELECT id FROM formularios WHERE titulo LIKE 'Plan de Acci%n 2024%' ORDER BY id DESC LIMIT 1);
SELECT @formulario AS formulario_id_encontrado, (SELECT titulo FROM formularios WHERE id = @formulario) AS titulo;
SET @ef = 2;
SET @anio = 2024;
SET @base = (SELECT COALESCE(MAX(id), 0) FROM formulacion_144);

-- Tabla de apoyo: para cada línea-motor-proyecto (L1-M1-P1...) toma el NOMBRE EXACTO del catálogo por su código. El sistema une los
-- indicadores con el catálogo por nombre, y debe coincidir letra por letra (puntos finales, tildes, etc.). Si un código no existe en el
-- catálogo se usa el nombre que trae el Excel. La tabla se borra al final del script.
DROP TABLE IF EXISTS tmp_lmp_2024;
CREATE TABLE tmp_lmp_2024 (lc VARCHAR(10), mc VARCHAR(10), pc VARCHAR(10), linea VARCHAR(500), objetivo TEXT, motor VARCHAR(500), proyecto VARCHAR(600)) DEFAULT CHARSET=utf8mb4;

-- Revisa aquí qué nombre quedó para cada código y si alguno salió del Excel (no estaba en el catálogo):
SELECT t.lc, t.mc, t.pc, t.linea, t.motor, t.proyecto FROM tmp_lmp_2024 t ORDER BY t.lc, t.mc, t.pc;

START TRANSACTION;


-- Distribución por facultades de los indicadores gestionados desde las facultades (valor de la vigencia)

COMMIT;

DROP TABLE IF EXISTS tmp_lmp_2024;

